auto HyperLogLogPresto<KeyType>::AddElem(KeyType val) -> void {
  // If m_ is 0, we can't add elements
  if (m_ == 0) {
    return;
  }

  // Calculate hash of the value
  hash_t hash = CalculateHash(val);

  // Convert hash to 64-bit binary
  std::bitset<64> binary(hash);

  // Extract the first n_bits_ bits to determine the register index
  uint16_t register_idx = 0;
  for (int i = 0; i < n_bits_; ++i) {
    if (binary[i]) {
      register_idx |= (1ULL << i);
    }
  }

  // Count the number of trailing zeros (rightmost contiguous zeros)
  uint64_t trailing_zeros = 0;
  for (int i = n_bits_; i < 64; ++i) {
    if (binary[i] == 0) {
      trailing_zeros++;
    } else {
      break;
    }
  }

  // Increment trailing_zeros by 1 to match the algorithm description
  trailing_zeros += 1;

  // Split the trailing_zeros into dense and overflow parts
  // Dense part: last DENSE_BUCKET_SIZE bits
  // Overflow part: remaining bits
  std::bitset<DENSE_BUCKET_SIZE> dense_part;
  std::bitset<OVERFLOW_BUCKET_SIZE> overflow_part;

  // Set the dense part (lower bits)
  for (int i = 0; i < DENSE_BUCKET_SIZE; ++i) {
    if (i < 64 && (trailing_zeros & (1ULL << i))) {
      dense_part.set(i);
    }
  }

  // Set the overflow part (higher bits)
  for (int i = 0; i < OVERFLOW_BUCKET_SIZE; ++i) {
    if (i + DENSE_BUCKET_SIZE < 64 && (trailing_zeros & (1ULL << (i + DENSE_BUCKET_SIZE)))) {
      overflow_part.set(i);
    }
  }

  // Update the dense bucket
  // If the new value is greater than the existing one, update it
  if (dense_part.to_ullong() > dense_bucket_[register_idx].to_ullong()) {
    dense_bucket_[register_idx] = dense_part;

    // If there are overflow bits, store them
    if (overflow_part.any()) {
      overflow_bucket_[register_idx] = overflow_part;
