auto HyperLogLogPresto<T>::ComputeCardinality() -> void {
  // If m_ is 0, cardinality is 0
  if (m_ == 0) {
    cardinality_ = 0;
    return;
  }

  // Calculate the sum of 2^(-value) for each register
  double sum = 0.0;
  for (uint64_t j = 0; j < m_; ++j) {
    // Get the value from dense bucket
    uint64_t value = dense_bucket_[j].to_ullong();

    // Add overflow bits if they exist
    auto it = overflow_bucket_.find(j);
    if (it != overflow_bucket_.end()) {
      value |= (it->second.to_ullong() << DENSE_BUCKET_SIZE);
    }

    // Add to sum
    sum += std::pow(2.0, -static_cast<double>(value));
  }

  // Calculate the cardinality using the formula
  double alpha_m_m = CONSTANT * m_ * m_;
  double estimate = alpha_m_m / sum;

  // Convert to the greatest integer less than or equal to the estimate
  cardinality_ = static_cast<uint64_t>(std::floor(estimate));
